991	// S5 apply: unsort expert_out then sg2_apply_step per ORIGINAL element. The
992	// expert output is in SORTED order; element i's value is expert_out_sorted[
993	// unsort[i]]. sg2_apply_step is the canonical csrc/algorithms math (CALLED).
994	template <typename Dims, typename ParamT, typename GradT>
995	__device__ __forceinline__ void sg2_stage_apply(
996	    ParamT* __restrict__ param,        // [N] tensor slice
997	    float* __restrict__ exp_avg, float* __restrict__ exp_avg_sq,
998	    float* __restrict__ mu_state, float* __restrict__ slow_state,
999	    const GradT* __restrict__ grad,    // [N] original order
1000	    const float* __restrict__ expert_out_sorted,  // [N] sorted
1001	    const int* __restrict__ unsort,    // [N] original-row -> sorted-row
1002	    float alpha, float gru_decay, float lamb_eff,
1003	    float lr, float beta1, float beta2, float eps, float wd,
1004	    float bc1, float bc2, int N) {
1005	    for (int i = threadIdx.x; i < N; i += blockDim.x) {
1006	        const float eo = expert_out_sorted[unsort[i]];
1007	        sg2alg::sg2_apply_step(
1008	            param, exp_avg, exp_avg_sq, mu_state, slow_state, grad,
1009	            eo, alpha, gru_decay, lamb_eff,
1010	            lr, beta1, beta2, eps, wd, bc1, bc2, (int64_t)i);
1011	    }
1012	}
