1014	// =====================================================================
1015	//  STAGE -1 — in-kernel SEGMENTED SORT (the composed-megakernel path's
1016	//  only big new device code). Per tensor, sort the [N] |grad| keys
1017	//  ASCENDING and write perm/unsort BEFORE S0. The standalone path
1018	//  pre-computes perm/unsort host-side (torch) and SKIPS this stage.
1019	//
1020	//  TIE SEMANTICS — STRATEGY A (index tie-break). The eager net + the per-op
1021	//  oracle sort by |grad| via torch.sort/argsort, which is UNSTABLE on CUDA.
1022	//  Reproducing an unstable order in a deterministic kernel is impossible, so
1023	//  we impose a TOTAL order by tie-breaking on the ORIGINAL index: the
1024	//  comparison key is the pair (|g|, idx) with SMALLER idx first on a |g| tie.
1025	//  This is (a) deterministic run-to-run (A/A/A-clean BY CONSTRUCTION — no
1026	//  scheduling dependence), and (b) the EXACT order the oracle's lock-step perm
1027	//  builder uses (the gate's tie-probe drives both with the same (|g|,idx) rule).
1028	//  For CONTINUOUS grads P(|g| tie)=0, so this coincides with any stable/unstable
1029	//  sort — the trajectory parity is unaffected; the tie-break only fixes the
1030	//  measure-zero tie set deterministically. A total order is ALSO required for the
1031	//  bitonic network to be correct (raw |g| with ties is not a total order).
1032	//
1033	//  ALGORITHM: a CTA-cooperative bitonic sort over Npow2 = next_pow2(N). The pad
1034	//  region [N, Npow2) is seeded with +INF keys (and idx>=N) so it sorts to the
1035	//  TOP (ascending) and never enters the first N output slots. One 256-thread CTA
1036	//  owns the whole tensor; grid-stride over Npow2 when Npow2 > blockDim.x.
1037	//  O(N log^2 N) — a STAGE-1 correctness cost, not a hot path.
1038	template <typename GradT>
1039	__device__ __forceinline__ void sg2_stage_segmented_sort(
1040	    const GradT* __restrict__ grad,   // [N] original order (tensor slice)
1041	    float* __restrict__ keys,         // [Npow2] scratch
1042	    int* __restrict__ idx,            // [Npow2] scratch
1043	    int* __restrict__ perm,           // [N] out: sorted-row -> original-row
1044	    int* __restrict__ unsort,         // [N] out: original-row -> sorted-row
1045	    int N) {
1046	    if (N <= 0) return;
1047	    // Npow2 = smallest power of two >= N.
1048	    int np2 = 1;
1049	    while (np2 < N) np2 <<= 1;
1050	    // Initialize keys/idx. Real elements get (|grad|, i); pad gets (+INF, i) with
1051	    // i>=N so the pad's index tie-break keeps it strictly above any real element
1052	    // sharing +INF (none do — real |g| is finite or NaN; NaN guarded to 0).
1053	    for (int i = threadIdx.x; i < np2; i += blockDim.x) {
1054	        if (i < N) {
1055	            float g = static_cast<float>(grad[i]);
1056	            if (!isfinite(g)) g = 0.0f;       // NaN/Inf guard (matches S0's guard)
1057	            keys[i] = fabsf(g);
1058	            idx[i]  = i;
1059	        } else {
1060	            keys[i] = INFINITY;
1061	            idx[i]  = i;                       // i>=N => sorts above all real rows
1062	        }
1063	    }
1064	    __syncthreads();
1065	    // Bitonic sort (ascending by (keys, idx)). For each (k, j) stage, thread t
1066	    // compares lane t with lane t^j; the swap direction is set by (t & k).
1067	    for (int k = 2; k <= np2; k <<= 1) {
1068	        for (int j = k >> 1; j > 0; j >>= 1) {
1069	            for (int t = threadIdx.x; t < np2; t += blockDim.x) {
1070	                const int ixj = t ^ j;
1071	                if (ixj > t) {
1072	                    // ascending block when (t & k)==0, descending otherwise.
1073	                    const bool ascending = ((t & k) == 0);
1074	                    const float ka = keys[t],   kb = keys[ixj];
1075	                    const int   ia = idx[t],    ib = idx[ixj];
1076	                    // (ka,ia) > (kb,ib) under the (|g|, idx) total order?
1077	                    const bool a_gt_b = (ka > kb) || (ka == kb && ia > ib);
1078	                    // swap so that the pair is in the block's required order.
1079	                    if (a_gt_b == ascending) {
1080	                        keys[t] = kb; keys[ixj] = ka;
1081	                        idx[t]  = ib; idx[ixj]  = ia;
1082	                    }
1083	                }
1084	            }
1085	            __syncthreads();
1086	        }
1087	    }
1088	    // perm[r] = idx[r] for r<N (the first N sorted slots are the real elements,
1089	    // since the +INF pad sorted to the top). Build unsort by scatter (race-free:
1090	    // each sorted row r writes its distinct original slot perm[r]).
1091	    for (int r = threadIdx.x; r < N; r += blockDim.x) {
1092	        const int src = idx[r];
1093	        perm[r] = src;
1094	        unsort[src] = r;
1095	    }
1096	    __syncthreads();
1097	}
