1099	// =====================================================================
1100	//  sg2_meta_stages<Dims> — the FULL per-tensor pipeline, CTA-local.
1101	//  Runs S0..S5 for ONE tensor (task id `t`) the calling CTA owns. All
1102	//  intermediates live in this CTA's workspace slice. __syncthreads()
1103	//  separates data-dependent stages WITHIN the CTA (the only coupling is
1104	//  this CTA's own rows; no cross-CTA dependence, hence no grid barrier).
1105	// =====================================================================
1106	// WeightsT is either SG2SmemWeights<Dims> (standalone: weights staged to smem)
1107	// or SG2Weights (composed megakernel: weights read from HBM — the SG2 bundle
1108	// does NOT fit smem alongside the model's DecTcSmem/VitTcSmem, see the launcher).
1109	// Both expose the SAME member names indexed as arrays, so the stage bodies are
1110	// identical. BuildSort=true runs STAGE -1 (in-kernel segmented sort) and consumes
1111	// ws.perm/ws.unsort; BuildSort=false consumes the pre-computed st.perm/st.unsort.
1112	template <typename Dims, typename WeightsT, typename ParamT, typename GradT,
1113	          bool BuildSort = false>
1114	__device__ void sg2_meta_stages(
1115	    const WeightsT& w,
1116	    int tid,                            // task (tensor) index
1117	    const SG2State& st,
1118	    const SG2Scalars& sc,
1119	    ParamT* __restrict__ param_base,    // packed params [total]
1120	    const GradT* __restrict__ grad_base,// packed grads  [total]
1121	    const float* __restrict__ sharp_base,// packed sharpness [total]
1122	    float* __restrict__ ws_base) {      // this CTA's workspace slice
1123	    constexpr int d = Dims::d_model;
1124	    const int N = st.n[tid];
1125	    if (N == 0) return;
1126	    const int64_t off = st.row_off[tid];
1127	    const int Nc = (N + Dims::csa_compress - 1) / Dims::csa_compress;
1128	    const int Nh = (N + Dims::hca_compress - 1) / Dims::hca_compress;
1129	    const int topk = (Dims::csa_topk < Nc) ? Dims::csa_topk : Nc;
1130	    const int topk1 = (topk > 0) ? topk : 1;
1131	
1132	    // Tensor-slice pointers.
1133	    ParamT* param = param_base + off;
1134	    const GradT* grad = grad_base + off;
1135	    const float* sharp = sharp_base + off;
1136	    float* exp_avg = st.exp_avg + off;
1137	    float* exp_avg_sq = st.exp_avg_sq + off;
1138	    float* mu = st.mu + off;
1139	    float* slow = st.slow + off;
1140	    float* gru_state = st.gru_state + off * Dims::gru_hidden;
1141	
1142	    // Workspace (carved for Nmax, used for this N).
1143	    SG2Work<Dims> ws = sg2_carve_ws<Dims>(ws_base, /*Nmax=*/N /*carved per tensor*/);
1144	    // NOTE: we carve at exactly N (not Nmax) so the buffers are tightly packed
1145	    // for THIS tensor — valid because ws_stride(Nmax) >= ws_stride(N). The host
1146	    // sizes the slice for Nmax; carving at N keeps the working set contiguous.
1147	
1148	    // STAGE -1: per-tensor segmented sort (composed path). The standalone path
1149	    // pre-computes perm/unsort host-side; there BuildSort=false skips this and the
1150	    // pointers come from st.perm/st.unsort.
1151	    const int* perm;
1152	    const int* unsort;
1153	    if constexpr (BuildSort) {
1154	        sg2_stage_segmented_sort<GradT>(grad, ws.sort_keys, ws.sort_idx,
1155	                                        ws.perm, ws.unsort, N);  // syncs internally
1156	        perm = ws.perm;
1157	        unsort = ws.unsort;
1158	    } else {
1159	        perm = st.perm + off;
1160	        unsort = st.unsort + off;
1161	    }
1162	
1163	    // S0: input projection + gather sorted features.
1164	    sg2_stage_input_proj_sorted<Dims>(w, grad, sharp, perm, ws.x_sorted, N);
1165	    __syncthreads();
1166	
1167	    // Build g_sorted / s_sorted (per-row scalars in sorted order) into the front
1168	    // of qI's buffer is unsafe (qI needed later); instead recompute from grad on
1169	    // the fly where needed (GRU/PEER read g_sorted[r] = grad[perm[r]]). To keep a
1170	    // single source we materialize them into new_gru-adjacent scratch: reuse the
1171	    // tail of expert_out? Too small. Simplest deterministic choice: store into
1172	    // dedicated columns we already have — qI is [N,rank] (rank>=4), so stash
1173	    // g_sorted in concat[:,0] / s_sorted in concat[:,1] BEFORE concat is used by
1174	    // attention? concat is used by out-proj. To avoid any aliasing we compute
1175	    // g_sorted/s_sorted lazily inside GRU/PEER via grad[perm[r]]. (No buffer.)
1176	
1177	    // S1: CSA context.
1178	    sg2_stage_project<Dims>(ws.x_sorted, w.csa_q_W, ws.q, N);             // q
1179	    sg2_stage_compress<Dims, /*IsCsa=*/true>(ws.x_sorted, w.csa_k_W, w.csa_compress_w, ws.c_k, N, Nc);
1180	    sg2_stage_compress<Dims, /*IsCsa=*/true>(ws.x_sorted, w.csa_v_W, w.csa_compress_w, ws.c_v, N, Nc);
1181	    sg2_stage_project<Dims>(ws.x_sorted, w.csa_k_W, ws.win_k, N);         // window k
1182	    sg2_stage_project<Dims>(ws.x_sorted, w.csa_v_W, ws.win_v, N);         // window v
1183	    sg2_stage_indexer_q<Dims>(ws.x_sorted, w.csa_idx_DQ, ws.qI, N);
1184	    sg2_stage_indexer_k<Dims>(ws.x_sorted, w.csa_idx_K, w.csa_compress_w, ws.kI, N, Nc);
1185	    __syncthreads();
1186	    sg2_stage_topk<Dims>(ws.qI, ws.kI, ws.sel, N, Nc, topk1);
1187	    __syncthreads();
1188	    sg2_stage_csa_attention<Dims>(ws.q, ws.c_k, ws.c_v, ws.win_k, ws.win_v,
1189	                                  ws.sel, ws.concat, N, Nc, topk1);
1190	    __syncthreads();
1191	    sg2_stage_out_proj<Dims>(ws.concat, w.csa_out_W, ws.csa_ctx, N);
1192	    __syncthreads();
1193	
1194	    // S2: HCA context (reuse q/c_k/c_v/win_k/win_v/concat scratch).
1195	    sg2_stage_project<Dims>(ws.x_sorted, w.hca_q_W, ws.q, N);
1196	    sg2_stage_compress<Dims, /*IsCsa=*/false>(ws.x_sorted, w.hca_k_W, nullptr, ws.c_k, N, Nh);
1197	    sg2_stage_compress<Dims, /*IsCsa=*/false>(ws.x_sorted, w.hca_v_W, nullptr, ws.c_v, N, Nh);
1198	    sg2_stage_project<Dims>(ws.x_sorted, w.hca_k_W, ws.win_k, N);
1199	    sg2_stage_project<Dims>(ws.x_sorted, w.hca_v_W, ws.win_v, N);
1200	    __syncthreads();
1201	    sg2_stage_hca_attention<Dims>(ws.q, ws.c_k, ws.c_v, ws.win_k, ws.win_v,
1202	                                  ws.concat, N, Nh);
1203	    __syncthreads();
1204	    sg2_stage_out_proj<Dims>(ws.concat, w.hca_out_W, ws.hca_ctx, N);
1205	    __syncthreads();
1206	
1207	    // g_sorted/s_sorted are read by GRU+PEER as grad[perm[r]]/sharp[perm[r]].
1208	    // To avoid recomputing the perm gather inside two stages, materialize them
1209	    // once into ws.q[:,0] and ws.q[:,1] (q is free now — attention consumed it).
1210	    for (int r = threadIdx.x; r < N; r += blockDim.x) {
1211	        const int src = perm[r];
1212	        float g = static_cast<float>(grad[src]);
1213	        float s = sharp[src];
1214	        if (!isfinite(g)) g = 0.0f;
1215	        if (!isfinite(s)) s = 0.0f;
1216	        ws.q[r * d + 0] = g;   // g_sorted
1217	        ws.q[r * d + 1] = s;   // s_sorted
1218	    }
1219	    __syncthreads();
1220	    // Strided views: g_sorted at stride d offset 0, s_sorted at stride d offset 1.
1221	    // The GRU/PEER stages take contiguous [N] g/s; build them into win_k[:,0]/
1222	    // win_k[:,1] contiguous? Simpler: pass strided access via small wrappers.
1223	    // We instead copy to contiguous front of win_k (free) and win_v (free).
1224	    for (int r = threadIdx.x; r < N; r += blockDim.x) {
1225	        ws.win_k[r] = ws.q[r * d + 0];   // g_sorted contiguous
1226	        ws.win_v[r] = ws.q[r * d + 1];   // s_sorted contiguous
1227	    }
1228	    __syncthreads();
1229	    const float* g_sorted = ws.win_k;   // [N]
1230	    const float* s_sorted = ws.win_v;   // [N]
1231	
1232	    // S3: matrix-GRU forward (writes new_gru sorted + persists gru_state).
1233	    sg2_stage_gru<Dims>(w, g_sorted, s_sorted, ws.csa_ctx, ws.hca_ctx,
1234	                        perm, gru_state, ws.new_gru, N);
1235	    __syncthreads();
1236	
1237	    // S4: PEER routing + experts → expert_out (sorted), scaled by rescale.
1238	    sg2_stage_peer<Dims>(w, ws.new_gru, ws.csa_ctx, ws.hca_ctx,
1239	                         g_sorted, s_sorted, ws.expert_out, sc.rescale, N);
1240	    __syncthreads();
1241	
1242	    // S5: unsort + sg2_apply_step (canonical math).
1243	    sg2_stage_apply<Dims>(
1244	        param, exp_avg, exp_avg_sq, mu, slow, grad, ws.expert_out, unsort,
1245	        sc.alpha[tid], sc.gru_decay[tid], sc.lamb_eff[tid],
1246	        sc.lr, sc.beta1[tid], sc.beta2, sc.eps, sc.wd,
1247	        sc.bc1[tid], sc.bc2[tid], N);
1248	    __syncthreads();
1249	}
