1251	// =====================================================================
1252	//  The persistent megakernel: ONE launch runs the SG2 optimizer step for
1253	//  ALL parameter tensors. gridDim.x = #SMs, 256 thr/CTA. Each CTA pulls
1254	//  WHOLE tensors from the task queue and runs sg2_meta_stages for each.
1255	//  ONE grid barrier at the end (so a composing model stage can reset the
1256	//  queue). The weight bundle is staged into smem ONCE per CTA up front.
1257	// =====================================================================
1258	// SG_TUNED_MEGA_BLOCK — unified with the fused megakernel's block-thread dim
1259	// (csrc/fused/sm_90/fused_megakernel.cuh). Default 256 (byte-identical untuned
1260	// build). NEEDS-PARITY before shipping a non-default winner (per-head PEER
1261	// routing + scan tiling assume the 256-thread shape).
1262	#ifndef SG_TUNED_MEGA_BLOCK
1263	#define SG_TUNED_MEGA_BLOCK 256
1264	#endif
1265	
1266	template <typename Dims, typename ParamT, typename GradT>
1267	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
1268	sg2_meta_optimizer_megakernel(
1269	    PersistentContext ctx,
1270	    SG2Weights w,
1271	    SG2State st,
1272	    SG2Scalars sc,
1273	    ParamT* __restrict__ params,
1274	    const GradT* __restrict__ grads,
1275	    const float* __restrict__ sharpness) {
1276	    // Stage the (small) weight bundle into shared memory once per CTA.
1277	    __shared__ SG2SmemWeights<Dims> sw;
1278	    sg2_stage_weights<Dims>(sw, w);
1279	    __syncthreads();
1280	
1281	    GridBarrier bar = ctx.barrier();
1282	    float* my_ws = st.workspace + (int64_t)blockIdx.x * st.ws_stride;
1283	
1284	    // Work-steal WHOLE tensors. Each tensor's full pipeline is CTA-local.
1285	    __shared__ int task_slot;
1286	    TaskQueue q = ctx.queue();
1287	    for (int t = q.next_block(&task_slot); t < st.n_tensors;
1288	         t = q.next_block(&task_slot)) {
1289	        sg2_meta_stages<Dims, SG2SmemWeights<Dims>, ParamT, GradT,
1290	                        /*BuildSort=*/false>(
1291	            sw, t, st, sc, params, grads, sharpness, my_ws);
1292	    }
1293	
1294	    // ONE grid barrier: lets a composing model stage reset the queue after the
1295	    // optimizer tail drains. (Standalone, this is just a clean exit fence.)
1296	    bar.sync();
1297	}
1298	
1299	// =====================================================================
1300	//  Host launcher — one persistent CTA per SM, SG_TUNED_MEGA_BLOCK thr/CTA.
1301	//  Mirrors launch_fused_decoder_megakernel's hang-freedom contract:
1302	//  occupancy>=1 or refuse (the GridBarrier rendezvous of n_ctas CTAs can
1303	//  never complete if a CTA cannot be placed). Zeroes the barrier+queue
1304	//  counters per launch. The caller allocates the workspace + index buffers
1305	//  and PRE-COMPUTES perm/unsort (the one explicit pre-kernel sort step).
1306	// =====================================================================
1307	template <typename Dims, typename ParamT, typename GradT>
1308	cudaError_t launch_sg2_meta_optimizer_tail(
1309	    PersistentContext ctx,
1310	    SG2Weights w, SG2State st, SG2Scalars sc,
1311	    ParamT* params, const GradT* grads, const float* sharpness,
1312	    cudaStream_t stream) {
1313	    int dev = 0;
1314	    cudaError_t err = cudaGetDevice(&dev);
1315	    if (err != cudaSuccess) return err;
1316	    int n_sms = 0;
1317	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1318	    if (err != cudaSuccess) return err;
1319	
1320	    int occ = 0;
1321	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1322	        &occ, (const void*)&sg2_meta_optimizer_megakernel<Dims, ParamT, GradT>,
1323	        SG_TUNED_MEGA_BLOCK, /*dynamicSMemBytes=*/0);
1324	    if (err != cudaSuccess) return err;
1325	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1326	
1327	    const unsigned launch_ctas = (unsigned)n_sms;
1328	    ctx.n_ctas = launch_ctas;
1329	    ctx.n_tasks = st.n_tensors;
1330	
1331	    if (ctx.g_arrived)   { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1332	    if (ctx.g_generation){ err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1333	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1334	
1335	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
1336	    sg2_meta_optimizer_megakernel<Dims, ParamT, GradT><<<grid, block, 0, stream>>>(
1337	        ctx, w, st, sc, params, grads, sharpness);
1338	    return cudaGetLastError();
1339	}
