1	#pragma once
2	// AdamW — vendor-neutral algorithm header.
3	//
4	// Reference: Loshchilov & Hutter 2017, "Decoupled Weight Decay
5	// Regularization" (https://arxiv.org/abs/1711.05101), Algorithm 2.
6	//
7	// Math (decoupled weight decay variant):
8	//   m_t = beta1 * m_{t-1} + (1 - beta1) * g
9	//   v_t = beta2 * v_{t-1} + (1 - beta2) * g^2
10	//   m_hat = m_t / (1 - beta1^t)        [bias correction]
11	//   v_hat = v_t / (1 - beta2^t)        [bias correction]
12	//   p -= lr * (m_hat / (sqrt(v_hat) + eps) + wd * p)
13	//
14	// Per-element step function called from inside a grid-stride loop in the
15	// per-backend launch kernel. Compiles under nvcc (CUDA) and hipcc (HIP).
16	// Pallas/JAX implements the same math directly in launch_adamw.py.
17	//
18	// Calling convention: bc1, bc2 are passed un-inverted —
19	//   bc1 = 1 - beta1^t,  bc2 = 1 - beta2^t
20	// — matching the binding code in csrc/bindings/bindings.cpp and the Python
21	// reference (`bc1 = 1.0 - beta1 ** step`). The step function divides by
22	// them to obtain the bias-corrected moments.
23	
24	#include "csrc/common/types.h"
25	#include "csrc/common/utils.cuh"
26	
27	namespace sg { namespace algorithms {
28	
29	template <typename ParamT, typename GradT>
30	__device__ __forceinline__ void adamw_step(
31	    ParamT* __restrict__ param,
32	    float* __restrict__ exp_avg,
33	    float* __restrict__ exp_avg_sq,
34	    const GradT* __restrict__ grad,
35	    const float lr,
36	    const float beta1,
37	    const float beta2,
38	    const float eps,
39	    const float wd,
40	    const float bc1,   // 1 - beta1^t (un-inverted; header divides by it)
41	    const float bc2,   // 1 - beta2^t (un-inverted; header divides by it)
42	    const int64_t idx
43	) {
44	    const float g  = static_cast<float>(grad[idx]);
45	    const float p  = static_cast<float>(param[idx]);
46	    const float m0 = exp_avg[idx];
47	    const float v0 = exp_avg_sq[idx];
48	
49	    const float m = beta1 * m0 + (1.0f - beta1) * g;
50	    const float v = beta2 * v0 + (1.0f - beta2) * g * g;
51	
52	    // Bias correction: m_hat = m / (1 - beta1^t), v_hat = v / (1 - beta2^t).
53	    const float m_hat = m / sg_safe_bc(bc1);
54	    const float v_hat = v / sg_safe_bc(bc2);
55	
56	    const float denom = sqrtf(v_hat) + eps;
57	    const float update = m_hat / denom;
58	
59	    exp_avg[idx]    = m;
60	    exp_avg_sq[idx] = v;
61	    param[idx]      = static_cast<ParamT>(p - lr * (update + wd * p));
62	}
63	
64	// FP32 vec4 fast path — process 4 elements per call.
65	__device__ __forceinline__ void adamw_step_vec4(
66	    float4* __restrict__ param4,
67	    float4* __restrict__ exp_avg4,
68	    float4* __restrict__ exp_avg_sq4,
69	    const float4* __restrict__ grad4,
70	    const float lr,
71	    const float beta1,
72	    const float beta2,
73	    const float eps,
74	    const float wd,
75	    const float bc1,
76	    const float bc2,
77	    const int64_t i
78	) {
79	    float4 p  = param4[i];
80	    float4 m0 = exp_avg4[i];
81	    float4 v0 = exp_avg_sq4[i];
82	    float4 g  = grad4[i];
83	
84	    float4 m;
85	    m.x = beta1 * m0.x + (1.0f - beta1) * g.x;
86	    m.y = beta1 * m0.y + (1.0f - beta1) * g.y;
87	    m.z = beta1 * m0.z + (1.0f - beta1) * g.z;
88	    m.w = beta1 * m0.w + (1.0f - beta1) * g.w;
89	
90	    float4 v;
91	    v.x = beta2 * v0.x + (1.0f - beta2) * g.x * g.x;
92	    v.y = beta2 * v0.y + (1.0f - beta2) * g.y * g.y;
93	    v.z = beta2 * v0.z + (1.0f - beta2) * g.z * g.z;
94	    v.w = beta2 * v0.w + (1.0f - beta2) * g.w * g.w;
95	
96	    // bc1, bc2 un-inverted: divide for bias correction.
97	    p.x -= lr * ((m.x / sg_safe_bc(bc1)) / (sqrtf(v.x / sg_safe_bc(bc2)) + eps) + wd * p.x);
98	    p.y -= lr * ((m.y / sg_safe_bc(bc1)) / (sqrtf(v.y / sg_safe_bc(bc2)) + eps) + wd * p.y);
99	    p.z -= lr * ((m.z / sg_safe_bc(bc1)) / (sqrtf(v.z / sg_safe_bc(bc2)) + eps) + wd * p.z);
100	    p.w -= lr * ((m.w / sg_safe_bc(bc1)) / (sqrtf(v.w / sg_safe_bc(bc2)) + eps) + wd * p.w);
101	
102	    param4[i]      = p;
103	    exp_avg4[i]    = m;
104	    exp_avg_sq4[i] = v;
105	}
106	
107	}} // namespace sg::algorithms
