1	#pragma once
2	// =============================================================================
3	// supergrok2_bilevel_adjoint.h — vendor-neutral, ATen-based, hand-written
4	// adjoint for the SuperGrok2 (SG2) CSA/HCA bilevel meta-net.
5	//
6	// This header is shared by BOTH backends:
7	//   - sm_90  (csrc/.../supergrok2_sm90.cuh, nvcc TU — ATen host orchestration)
8	//   - gfx942 (csrc/.../supergrok2_gfx942.hip.hpp, host-compiler TU — ATen)
9	//
10	// It implements a REAL reverse-mode VJP (NO torch::autograd, NO autograd graph,
11	// NO grad-tracking tensors) through the differentiable forward defined by the
12	// oracle CSAHCAMetaNet.forward_for_bilevel (grokking_optimizers/optimizers/
13	// supergrok2.py:734). Every backward expression below is the analytic adjoint
14	// of the corresponding ATen forward op, derived by hand and composed in reverse
15	// pipeline order:
16	//
17	//   input_proj+sort -> CSA -> HCA -> GRU -> PEER product-key routing + expert
18	//   MLP -> smart_grad = grad + rescale * expert_out
19	//
20	// Adjoint (reverse) order:
21	//   smart_grad -> expert MLP + routing -> GRU gates -> HCA dense-attn ->
22	//   CSA sparse-attn (incl. learned-pool compression + lightning indexer) ->
23	//   input_proj (scatter via sort_indices).
24	//
25	// CHECKPOINTING CHOICE (documented; honors checkpoint_interval <= 32):
26	//   fwd_save persists the |g|-sorted input x_sorted, the sort permutation, the
27	//   two heavy contexts (csa_ctx, hca_ctx), the attention softmax denominators /
28	//   selected-index sets / probs, the GRU gates, and the PEER product-key /
29	//   routing saved tensors. The backward RECOMPUTES the cheap per-row q/k/v and
30	//   indexer projections (and the small compressed K/V pools) from x_sorted
31	//   rather than saving them — i.e. activation checkpointing at the layer
32	//   boundary. checkpoint_interval is accepted and threaded through; for this
33	//   first correct cut the recompute granularity is "every layer" (the contexts
34	//   themselves are always saved by fwd_save), which is a strict superset of any
35	//   interval <= MAX_CKPT_INTERVAL=32. No information is dropped.
36	//
37	// All math is FP32. Output weight-grad buffers are zero-init by the caller and
38	// this code adds into them (accumulate semantics, matching the spec contract).
39	// =============================================================================
40	
41	#include <torch/extension.h>
42	#include <ATen/ATen.h>
43	#include <cmath>
44	#include <limits>
45	#include <vector>
46	#include <tuple>
47	
48	namespace sg { namespace algorithms { namespace sg2_bilevel {
49	
50	using torch::Tensor;
51	using namespace torch::indexing;
52	
53	// ─────────────────────────────────────────────────────────────────────────
54	//  Saved-activation bundle produced by the forward-save and consumed by the
55	//  backward. Kept as a small struct for the in-process fast path; the public
56	//  launchers marshal the relevant members into the bindings-declared tensors.
57	// ─────────────────────────────────────────────────────────────────────────
58	struct SavedActs {
59	    // pipeline-level
60	    Tensor x_sorted;        // [N, d] |g|-sorted input_proj output
61	    Tensor sort_idx;        // [N] long: g.abs().argsort()  (ascending)
62	    Tensor unsort_idx;      // [N] long: sort_idx.argsort()
63	    Tensor csa_ctx;         // [N, d] (unsorted)
64	    Tensor hca_ctx;         // [N, d] (unsorted)
65	    // CSA attention adjoint state
66	    Tensor csa_denom;       // [N, H] log-sum-exp denom (saved, informational)
67	    Tensor csa_sel_idx;     // [N, topk] selected compressed entries (long)
68	    Tensor csa_probs;       // [N, H, topk+wsz] softmax probs
69	    // HCA attention adjoint state
70	    Tensor hca_denom;       // [H, N] denom (informational)
71	    Tensor hca_probs;       // [H, N, Nh+win] softmax probs
72	    // GRU
73	    Tensor gru_input;       // [N, gru_in] = cat(g, s, csa_ctx, hca_ctx)
74	    Tensor gru_h_old;       // [N, gru_hidden]
75	    Tensor gru_z;           // [N, gru_hidden]
76	    Tensor gru_r;           // [N, gru_hidden]
77	    Tensor gru_h_tilde;     // [N, gru_hidden]
78	    Tensor gru_new;         // [N, gru_hidden]
79	    // PEER
80	    Tensor peer_input;      // [N, peer_in] = cat(gru_new, csa_ctx, hca_ctx, g, s)
81	    Tensor g_col;           // [N] grad (original order)
82	    Tensor s_col;           // [N] sharpness (original order)
83	};
84	
85	// =========================================================================
86	//  Small helpers
87	// =========================================================================
88	
89	// nn.Linear forward: y = x @ W.t() + b  (b optional).
90	static inline Tensor linear_fwd(const Tensor& x, const Tensor& W,
91	                                const Tensor& b = Tensor{}) {
92	    auto y = torch::mm(x, W.t());
93	    if (b.defined()) y = y + b.unsqueeze(0);
94	    return y;
95	}
96	
97	// =========================================================================
98	//  CSA forward — mirrors _csa_body (supergrok2.py:435). Returns ctx_pre_out
99	//  ([N,d], BEFORE out_W) plus all intermediates needed for the backward.
100	// =========================================================================
101	struct CsaFwd {
102	    Tensor ctx;        // [N, d] pre-out_W context
103	    Tensor q, k_tok, v_tok;       // [N, d]
104	    Tensor pool_w;                 // [win]
105	    Tensor w_eff;                  // [Nc, win]
106	    Tensor gather_c;               // [Nc, win] long
107	    Tensor valid;                  // [Nc, win] bool
108	    Tensor c_k, c_v;               // [Nc, d]
109	    Tensor qI, kI_tok, c_kI;       // [N,d],[N,d],[Nc,d]
110	    Tensor sel;                    // [N, topk] long
111	    Tensor sel_vh;                 // [N, topk, H, hd]
112	    Tensor win_v;                  // [N, wsz, H, hd]
113	    Tensor win_idx_c;              // [N, wsz] long
114	    Tensor win_valid;              // [N, wsz] bool
115	    Tensor attn;                   // [N, H, topk+wsz]
116	    int64_t Nc, topk, wsz;
117	};
118	
119	static CsaFwd csa_forward(
120	    const Tensor& x, const Tensor& q_W, const Tensor& k_W, const Tensor& v_W,
121	    const Tensor& compress_w, const Tensor& idx_DQ, const Tensor& idx_UQ,
122	    const Tensor& idx_K, int64_t num_heads, int64_t csa_compress,
123	    int64_t csa_window, int64_t csa_topk)
124	{
125	    CsaFwd f;
126	    const auto N = x.size(0);
127	    const auto d = x.size(1);
128	    const auto head_dim = d / num_heads;
129	    const double scale = 1.0 / std::sqrt((double)head_dim);
130	    const double sqrt_d = std::sqrt((double)d);
131	    auto lopt = torch::TensorOptions().dtype(torch::kLong).device(x.device());
132	
133	    f.q     = linear_fwd(x, q_W);
134	    f.k_tok = linear_fwd(x, k_W);
135	    f.v_tok = linear_fwd(x, v_W);
136	
137	    const int64_t stride = csa_compress;
138	    const int64_t win    = csa_window;
139	    const int64_t nc     = (N + stride - 1) / stride;
140	    f.Nc = nc;
141	
142	    f.pool_w = torch::softmax(compress_w, 0);                 // [win]
143	    auto starts = torch::arange(nc, lopt) * stride;
144	    auto offs   = torch::arange(win, lopt);
145	    auto gather = starts.unsqueeze(1) + offs.unsqueeze(0);    // [Nc, win]
146	    f.valid  = gather < N;
147	    f.gather_c = gather.clamp_max(N - 1);
148	    auto w_eff = f.pool_w.unsqueeze(0) * f.valid.to(torch::kFloat32);
149	    w_eff = w_eff / w_eff.sum(1, true).clamp_min(1e-12);
150	    f.w_eff = w_eff;
151	
152	    f.c_k = (f.k_tok.index({f.gather_c}) * w_eff.unsqueeze(-1)).sum(1);  // [Nc,d]
153	    f.c_v = (f.v_tok.index({f.gather_c}) * w_eff.unsqueeze(-1)).sum(1);  // [Nc,d]
154	
155	    // lightning indexer
156	    f.qI     = torch::mm(torch::mm(x, idx_DQ), idx_UQ);      // [N, d]
157	    f.kI_tok = torch::mm(torch::mm(x, idx_K), idx_UQ);       // [N, d]
158	    f.c_kI   = (f.kI_tok.index({f.gather_c}) * w_eff.unsqueeze(-1)).sum(1);  // [Nc,d]
159	    auto idx_scores = torch::mm(f.qI, f.c_kI.t()) / sqrt_d;  // [N, Nc]
160	    const int64_t topk = std::min<int64_t>(csa_topk, nc);
161	    f.topk = topk;
162	    f.sel = std::get<1>(idx_scores.topk(topk, -1));          // [N, topk]
163	
164	    auto sel_k = f.c_k.index({f.sel});                       // [N, topk, d]
165	    auto sel_v = f.c_v.index({f.sel});                       // [N, topk, d]
166	    auto sel_kh = sel_k.reshape({N, topk, num_heads, head_dim});
167	    f.sel_vh = sel_v.reshape({N, topk, num_heads, head_dim});
168	    auto qh = f.q.reshape({N, num_heads, head_dim});
169	    auto comp_scores = torch::einsum("nhd,nkhd->nhk", {qh, sel_kh}) * scale;
170	
171	    const int64_t wsz = std::min<int64_t>(win, N);
172	    f.wsz = wsz;
173	    auto woffs = torch::arange(wsz, lopt);
174	    auto qpos  = torch::arange(N, lopt).unsqueeze(1);
175	    auto win_idx = qpos - woffs.unsqueeze(0);                // [N, wsz]
176	    f.win_valid = win_idx >= 0;
177	    f.win_idx_c = win_idx.clamp_min(0);
178	    auto win_k = f.k_tok.index({f.win_idx_c}).reshape({N, wsz, num_heads, head_dim});
179	    f.win_v    = f.v_tok.index({f.win_idx_c}).reshape({N, wsz, num_heads, head_dim});
180	    auto win_scores = torch::einsum("nhd,nwhd->nhw", {qh, win_k}) * scale;
181	    win_scores = win_scores.masked_fill(
182	        f.win_valid.logical_not().unsqueeze(1),
183	        -std::numeric_limits<float>::infinity());
184	
185	    auto all_scores = torch::cat({comp_scores, win_scores}, -1);  // [N,H,topk+wsz]
186	    f.attn = torch::softmax(all_scores, -1);
187	    auto attn_c = f.attn.index({Slice(), Slice(), Slice(0, topk)});
188	    auto attn_w = f.attn.index({Slice(), Slice(), Slice(topk, None)});
189	    auto ctx_h = torch::einsum("nhk,nkhd->nhd", {attn_c, f.sel_vh})
190	               + torch::einsum("nhw,nwhd->nhd", {attn_w, f.win_v});
191	    f.ctx = ctx_h.reshape({N, d});
192	    return f;
193	}
194	
195	// CSA backward: given d_ctx_pre (grad wrt pre-out_W ctx [N,d]) accumulate the
196	// weight grads (q/k/v/compress/idx) into the d_* buffers. Recomputes nothing
197	// beyond what CsaFwd already holds (passed in). Returns nothing.
198	static void csa_backward(
199	    const Tensor& x, const CsaFwd& f,
200	    const Tensor& q_W, const Tensor& k_W, const Tensor& v_W,
201	    const Tensor& compress_w, const Tensor& idx_DQ, const Tensor& idx_UQ,
202	    const Tensor& idx_K, int64_t num_heads,
203	    const Tensor& d_ctx,            // [N, d] grad wrt pre-out_W ctx
204	    Tensor& d_q_W, Tensor& d_k_W, Tensor& d_v_W,
205	    Tensor& d_compress_w, Tensor& d_idx_DQ, Tensor& d_idx_UQ, Tensor& d_idx_K,
206	    Tensor& d_x_out)                // [N, d] accumulate grad wrt x
207	{
208	    const auto N = x.size(0);
209	    const auto d = x.size(1);
210	    const auto head_dim = d / num_heads;
211	    const double scale = 1.0 / std::sqrt((double)head_dim);
212	    const double sqrt_d = std::sqrt((double)d);
213	    const int64_t topk = f.topk, wsz = f.wsz, Nc = f.Nc, win = f.pool_w.size(0);
214	
215	    auto qh = f.q.reshape({N, num_heads, head_dim});
216	    auto attn_c = f.attn.index({Slice(), Slice(), Slice(0, topk)});  // [N,H,topk]
217	    auto attn_w = f.attn.index({Slice(), Slice(), Slice(topk, None)});// [N,H,wsz]
218	
219	    // ctx_h = einsum(attn_c, sel_vh) + einsum(attn_w, win_v)
220	    auto d_ctx_h = d_ctx.reshape({N, num_heads, head_dim});          // [N,H,hd]
221	
222	    // d attn_c, d sel_vh
223	    auto d_attn_c = torch::einsum("nhd,nkhd->nhk", {d_ctx_h, f.sel_vh});  // [N,H,topk]
224	    auto d_sel_vh = torch::einsum("nhk,nhd->nkhd", {attn_c, d_ctx_h});    // [N,topk,H,hd]
225	    auto d_attn_w = torch::einsum("nhd,nwhd->nhw", {d_ctx_h, f.win_v});   // [N,H,wsz]
226	    auto d_win_v  = torch::einsum("nhw,nhd->nwhd", {attn_w, d_ctx_h});    // [N,wsz,H,hd]
227	
228	    // softmax backward over the joint axis [topk+wsz]
229	    auto d_attn = torch::cat({d_attn_c, d_attn_w}, -1);              // [N,H,topk+wsz]
230	    auto dot = (d_attn * f.attn).sum(-1, true);                     // [N,H,1]
231	    auto d_scores = f.attn * (d_attn - dot);                        // [N,H,topk+wsz]
232	    auto d_comp_scores = d_scores.index({Slice(), Slice(), Slice(0, topk)});  // [N,H,topk]
233	    auto d_win_scores  = d_scores.index({Slice(), Slice(), Slice(topk, None)});// [N,H,wsz]
234	    // masked positions contributed 0 to softmax; zero their grad explicitly.
235	    d_win_scores = d_win_scores.masked_fill(
236	        f.win_valid.logical_not().unsqueeze(1), 0.0f);
237	
238	    // comp_scores = einsum(qh, sel_kh)*scale  → d qh, d sel_kh
239	    auto sel_k = f.c_k.index({f.sel});                              // [N,topk,d]
240	    auto sel_kh = sel_k.reshape({N, topk, num_heads, head_dim});
241	    auto d_qh_c   = torch::einsum("nhk,nkhd->nhd", {d_comp_scores, sel_kh}) * scale;
242	    auto d_sel_kh = torch::einsum("nhk,nhd->nkhd", {d_comp_scores, qh}) * scale;
243	
244	    // win_scores = einsum(qh, win_k)*scale
245	    auto win_k = f.k_tok.index({f.win_idx_c}).reshape({N, wsz, num_heads, head_dim});
246	    auto d_qh_w  = torch::einsum("nhw,nwhd->nhd", {d_win_scores, win_k}) * scale;
247	    auto d_win_k = torch::einsum("nhw,nhd->nwhd", {d_win_scores, qh}) * scale;
248	
249	    auto d_qh = d_qh_c + d_qh_w;                                    // [N,H,hd]
250	    auto d_q  = d_qh.reshape({N, d});                              // [N,d]
251	
252	    // ── scatter window grads back into d_k_tok / d_v_tok ──
253	    auto d_k_tok = torch::zeros_like(f.k_tok);                      // [N,d]
254	    auto d_v_tok = torch::zeros_like(f.v_tok);                      // [N,d]
255	    {
256	        auto idx_flat = f.win_idx_c.reshape({-1});                  // [N*wsz]
257	        auto valid_flat = f.win_valid.reshape({-1, 1}).to(torch::kFloat32);
258	        auto dwk = d_win_k.reshape({N * wsz, d}) * valid_flat;
259	        auto dwv = d_win_v.reshape({N * wsz, d}) * valid_flat;
260	        d_k_tok.index_add_(0, idx_flat, dwk);
261	        d_v_tok.index_add_(0, idx_flat, dwv);
262	    }
263	
264	    // ── selected-compressed value/key grads → d_c_v / d_c_k via scatter on sel ──
265	    auto d_c_k = torch::zeros_like(f.c_k);                          // [Nc,d]
266	    auto d_c_v = torch::zeros_like(f.c_v);
267	    {
268	        auto sel_flat = f.sel.reshape({-1});                       // [N*topk]
269	        // d_sel_kh [N,topk,H,hd] -> [N*topk, d]
270	        auto dskh = d_sel_kh.reshape({N * topk, d});
271	        auto dsvh = d_sel_vh.reshape({N * topk, d});
272	        d_c_k.index_add_(0, sel_flat, dskh);
273	        d_c_v.index_add_(0, sel_flat, dsvh);
274	    }
275	    // NOTE on top-k selection: the discrete top-k index set `sel` is treated as
276	    // a stop-gradient routing decision (its own ∂ is a measure-zero subgradient,
277	    // exactly as torch.topk reports no grad to the *indices*). Gradients flow
278	    // through the *values* gathered at those indices, which is what the scatter
279	    // above implements — identical to autograd's treatment of c_k[sel]/c_v[sel].
280	
281	    // ── compression backward: c_k = sum_w (k_tok[gather]*w_eff) ──
282	    // d_k_tok via gather scatter, d_w_eff from pooling.
283	    auto d_w_eff = torch::zeros_like(f.w_eff);                      // [Nc,win]
284	    auto pooled_k_grad_to_w = (f.k_tok.index({f.gather_c}) * d_c_k.unsqueeze(1)).sum(-1); // [Nc,win]
285	    auto pooled_v_grad_to_w = (f.v_tok.index({f.gather_c}) * d_c_v.unsqueeze(1)).sum(-1); // [Nc,win]
286	    d_w_eff = pooled_k_grad_to_w + pooled_v_grad_to_w;
287	    {
288	        // d_k_tok[gather] += w_eff * d_c_k ; same for v
289	        auto g_flat = f.gather_c.reshape({-1});                    // [Nc*win]
290	        auto wk = (d_c_k.unsqueeze(1) * f.w_eff.unsqueeze(-1)).reshape({Nc * win, d});
291	        auto wv = (d_c_v.unsqueeze(1) * f.w_eff.unsqueeze(-1)).reshape({Nc * win, d});
292	        d_k_tok.index_add_(0, g_flat, wk);
293	        d_v_tok.index_add_(0, g_flat, wv);
294	    }
295	
296	    // ── indexer backward ──
297	    // idx_scores = qI @ c_kI.t() / sqrt_d, used ONLY for top-k selection.
298	    // Selection is discrete (stop-grad), so idx_scores receives no grad through
299	    // the attention values. The indexer weights therefore get a soft surrogate
300	    // grad of zero from the discrete argmax — matching autograd, which returns
301	    // None for d/d(idx_*) of a pure topk-index path. We still compute the c_kI
302	    // compression contribution to d_w_eff = 0 here (consistency). The 🟡 mark in
303	    // HARDWARE_VALIDATION.md flags d_csa_idx_* as exactly-zero-by-construction
304	    // (the oracle likewise yields zero grad to idx_DQ/idx_UQ/idx_K because the
305	    // only consumer is a non-differentiable topk index).
306	    // d_idx_* accumulate 0; explicit no-op keeps buffers untouched.
307	    (void)idx_DQ; (void)idx_UQ; (void)idx_K; (void)sqrt_d;
308	    (void)d_idx_DQ; (void)d_idx_UQ; (void)d_idx_K;
309	
310	    // ── w_eff backward → pool_w (softmax(compress_w)) ──
311	    // w_eff = (pool_w * valid) / sum(pool_w*valid). Backward of the normalize:
312	    auto vmask = f.valid.to(torch::kFloat32);                       // [Nc,win]
313	    auto num = f.pool_w.unsqueeze(0) * vmask;                       // pre-normalize
314	    auto denom = num.sum(1, true).clamp_min(1e-12);                // [Nc,1]
315	    // w_eff = num/denom; d_num = (d_w_eff - (d_w_eff*w_eff).sum)/denom
316	    auto sum_dwe_w = (d_w_eff * f.w_eff).sum(1, true);             // [Nc,1]
317	    auto d_num = (d_w_eff - sum_dwe_w) / denom;                    // [Nc,win]
318	    auto d_pool_w_perrow = d_num * vmask;                         // [Nc,win]
319	    auto d_pool_w = d_pool_w_perrow.sum(0);                       // [win]
320	    // softmax backward: d_compress = pool_w * (d_pool_w - sum(d_pool_w*pool_w))
321	    auto sdp = (d_pool_w * f.pool_w).sum();
322	    auto d_compress = f.pool_w * (d_pool_w - sdp);                // [win]
323	    d_compress_w.add_(d_compress);
324	
325	    // ── project backwards: q/k/v = x @ W.t() ──
326	    // d_q_W += d_q.t() @ x ; (since y = x @ W.t(), dW = d_y.t() @ x)
327	    d_q_W.add_(torch::mm(d_q.t(), x));
328	    d_k_W.add_(torch::mm(d_k_tok.t(), x));
329	    d_v_W.add_(torch::mm(d_v_tok.t(), x));
330	    // d into x from q/k/v projections: d_x += d_y @ W  (y = x @ W.t()).
331	    d_x_out.add_(torch::mm(d_q, q_W));
332	    d_x_out.add_(torch::mm(d_k_tok, k_W));
333	    d_x_out.add_(torch::mm(d_v_tok, v_W));
334	    // (The lightning-indexer path contributes no grad to x because its only
335	    //  consumer is the non-differentiable top-k index — see note above.)
336	}
