338	// =========================================================================
339	//  HCA forward — mirrors _hca_body (supergrok2.py:493).
340	// =========================================================================
341	struct HcaFwd {
342	    Tensor ctx;                 // [N, d] pre-out_W
343	    Tensor q, k_tok, v_tok;
344	    Tensor w_eff;               // [Nh, stride]
345	    Tensor gather_c;            // [Nh, stride] long
346	    Tensor valid;               // [Nh, stride] bool
347	    Tensor c_k, c_v;            // [Nh, d]
348	    Tensor c_vh;                // [H, Nh, hd]
349	    Tensor win_vh;              // [H, N, win, hd]
350	    Tensor win_idx_c;           // [N, win] long
351	    Tensor win_valid;           // [N, win] bool
352	    Tensor attn;                // [H, N, Nh+win]
353	    int64_t Nh, win;
354	};
355	
356	static Tensor split_heads(const Tensor& t, int64_t num_heads, int64_t head_dim) {
357	    const auto L = t.size(0);
358	    return t.reshape({L, num_heads, head_dim}).permute({1, 0, 2}).contiguous();
359	}
360	
361	static HcaFwd hca_forward(
362	    const Tensor& x, const Tensor& q_W, const Tensor& k_W, const Tensor& v_W,
363	    int64_t num_heads, int64_t hca_compress, int64_t csa_window)
364	{
365	    HcaFwd f;
366	    const auto N = x.size(0);
367	    const auto d = x.size(1);
368	    const auto head_dim = d / num_heads;
369	    const double scale = 1.0 / std::sqrt((double)head_dim);
370	    auto lopt = torch::TensorOptions().dtype(torch::kLong).device(x.device());
371	
372	    f.q     = linear_fwd(x, q_W);
373	    f.k_tok = linear_fwd(x, k_W);
374	    f.v_tok = linear_fwd(x, v_W);
375	
376	    const int64_t stride = hca_compress;
377	    const int64_t nh = (N + stride - 1) / stride;
378	    f.Nh = nh;
379	    auto starts = torch::arange(nh, lopt) * stride;
380	    auto offs   = torch::arange(stride, lopt);
381	    auto gather = starts.unsqueeze(1) + offs.unsqueeze(0);
382	    f.valid = gather < N;
383	    f.gather_c = gather.clamp_max(N - 1);
384	    auto w_eff = f.valid.to(torch::kFloat32);
385	    w_eff = w_eff / w_eff.sum(1, true).clamp_min(1e-12);
386	    f.w_eff = w_eff;
387	    f.c_k = (f.k_tok.index({f.gather_c}) * w_eff.unsqueeze(-1)).sum(1);  // [Nh,d]
388	    f.c_v = (f.v_tok.index({f.gather_c}) * w_eff.unsqueeze(-1)).sum(1);
389	
390	    auto qh   = split_heads(f.q, num_heads, head_dim);     // [H,N,hd]
391	    auto c_kh = split_heads(f.c_k, num_heads, head_dim);   // [H,Nh,hd]
392	    f.c_vh    = split_heads(f.c_v, num_heads, head_dim);   // [H,Nh,hd]
393	    auto comp_scores = torch::einsum("hnd,hmd->hnm", {qh, c_kh}) * scale;
394	
395	    const int64_t win = std::min<int64_t>(csa_window, N);
396	    f.win = win;
397	    auto woffs = torch::arange(win, lopt);
398	    auto qpos  = torch::arange(N, lopt).unsqueeze(1);
399	    auto win_idx = qpos - woffs.unsqueeze(0);
400	    f.win_valid = win_idx >= 0;
401	    f.win_idx_c = win_idx.clamp_min(0);
402	    auto kh_full = split_heads(f.k_tok, num_heads, head_dim);  // [H,N,hd]
403	    auto vh_full = split_heads(f.v_tok, num_heads, head_dim);
404	    auto win_kh = kh_full.index({Slice(), f.win_idx_c, Slice()});  // [H,N,win,hd]
405	    f.win_vh    = vh_full.index({Slice(), f.win_idx_c, Slice()});
406	    auto win_scores = torch::einsum("hnd,hnwd->hnw", {qh, win_kh}) * scale;
407	    win_scores = win_scores.masked_fill(
408	        f.win_valid.logical_not().unsqueeze(0),
409	        -std::numeric_limits<float>::infinity());
410	
411	    auto all_scores = torch::cat({comp_scores, win_scores}, -1);   // [H,N,Nh+win]
412	    f.attn = torch::softmax(all_scores, -1);
413	    auto attn_c = f.attn.index({Slice(), Slice(), Slice(0, nh)});
414	    auto attn_w = f.attn.index({Slice(), Slice(), Slice(nh, None)});
415	    auto ctx_h = torch::einsum("hnm,hmd->hnd", {attn_c, f.c_vh})
416	               + torch::einsum("hnw,hnwd->hnd", {attn_w, f.win_vh});
417	    f.ctx = ctx_h.permute({1, 0, 2}).reshape({N, d});
418	    return f;
419	}
420	
421	static void hca_backward(
422	    const Tensor& x, const HcaFwd& f,
423	    const Tensor& q_W, const Tensor& k_W, const Tensor& v_W,
424	    int64_t num_heads, const Tensor& d_ctx,
425	    Tensor& d_q_W, Tensor& d_k_W, Tensor& d_v_W, Tensor& d_x_out)
426	{
427	    const auto N = x.size(0);
428	    const auto d = x.size(1);
429	    const auto head_dim = d / num_heads;
430	    const double scale = 1.0 / std::sqrt((double)head_dim);
431	    const int64_t Nh = f.Nh, win = f.win, stride_cols = f.w_eff.size(1);
432	
433	    auto qh   = split_heads(f.q, num_heads, head_dim);       // [H,N,hd]
434	    auto c_kh = split_heads(f.c_k, num_heads, head_dim);     // [H,Nh,hd]
435	    auto attn_c = f.attn.index({Slice(), Slice(), Slice(0, Nh)});  // [H,N,Nh]
436	    auto attn_w = f.attn.index({Slice(), Slice(), Slice(Nh, None)});// [H,N,win]
437	
438	    // d ctx -> [H,N,hd]
439	    auto d_ctx_h = d_ctx.reshape({N, num_heads, head_dim}).permute({1, 0, 2}).contiguous();
440	
441	    auto d_attn_c = torch::einsum("hnd,hmd->hnm", {d_ctx_h, f.c_vh});   // [H,N,Nh]
442	    auto d_c_vh   = torch::einsum("hnm,hnd->hmd", {attn_c, d_ctx_h});   // [H,Nh,hd]
443	    auto d_attn_w = torch::einsum("hnd,hnwd->hnw", {d_ctx_h, f.win_vh});// [H,N,win]
444	    auto d_win_vh = torch::einsum("hnw,hnd->hnwd", {attn_w, d_ctx_h});  // [H,N,win,hd]
445	
446	    auto d_attn = torch::cat({d_attn_c, d_attn_w}, -1);                 // [H,N,Nh+win]
447	    auto dot = (d_attn * f.attn).sum(-1, true);
448	    auto d_scores = f.attn * (d_attn - dot);
449	    auto d_comp_scores = d_scores.index({Slice(), Slice(), Slice(0, Nh)});  // [H,N,Nh]
450	    auto d_win_scores  = d_scores.index({Slice(), Slice(), Slice(Nh, None)});// [H,N,win]
451	    d_win_scores = d_win_scores.masked_fill(
452	        f.win_valid.logical_not().unsqueeze(0), 0.0f);
453	
454	    // comp_scores = einsum(qh, c_kh)*scale
455	    auto d_qh_c   = torch::einsum("hnm,hmd->hnd", {d_comp_scores, c_kh}) * scale;
456	    auto d_c_kh   = torch::einsum("hnm,hnd->hmd", {d_comp_scores, qh}) * scale;
457	
458	    // win_scores = einsum(qh, win_kh)*scale
459	    auto kh_full = split_heads(f.k_tok, num_heads, head_dim);
460	    auto win_kh = kh_full.index({Slice(), f.win_idx_c, Slice()});       // [H,N,win,hd]
461	    auto d_qh_w  = torch::einsum("hnw,hnwd->hnd", {d_win_scores, win_kh}) * scale;
462	    auto d_win_kh = torch::einsum("hnw,hnd->hnwd", {d_win_scores, qh}) * scale;
463	
464	    auto d_qh = d_qh_c + d_qh_w;                                       // [H,N,hd]
465	    // merge heads back: [H,N,hd] -> [N,d]
466	    auto d_q = d_qh.permute({1, 0, 2}).reshape({N, d});
467	
468	    // d_c_v from d_c_vh, d_c_k from d_c_kh  (split-head inverse)
469	    auto d_c_v = d_c_vh.permute({1, 0, 2}).reshape({Nh, d});           // [Nh,d]
470	    auto d_c_k = d_c_kh.permute({1, 0, 2}).reshape({Nh, d});
471	
472	    auto d_k_tok = torch::zeros_like(f.k_tok);
473	    auto d_v_tok = torch::zeros_like(f.v_tok);
474	
475	    // window scatter (win_kh/win_vh gathered from kh_full/vh_full along seq)
476	    {
477	        // d_win_kh [H,N,win,hd] -> per (n,w) token index win_idx_c[n,w], head-merged
478	        auto d_win_k = d_win_kh.permute({1, 2, 0, 3}).reshape({N * win, d});  // [N*win, d]
479	        auto d_win_v = d_win_vh.permute({1, 2, 0, 3}).reshape({N * win, d});
480	        auto idx_flat = f.win_idx_c.reshape({-1});
481	        auto valid_flat = f.win_valid.reshape({-1, 1}).to(torch::kFloat32);
482	        d_k_tok.index_add_(0, idx_flat, d_win_k * valid_flat);
483	        d_v_tok.index_add_(0, idx_flat, d_win_v * valid_flat);
484	    }
485	
486	    // compression scatter: c_k = sum_w (k_tok[gather]*w_eff); w_eff has no params
487	    {
488	        auto g_flat = f.gather_c.reshape({-1});                       // [Nh*stride]
489	        auto wk = (d_c_k.unsqueeze(1) * f.w_eff.unsqueeze(-1)).reshape({Nh * stride_cols, d});
490	        auto wv = (d_c_v.unsqueeze(1) * f.w_eff.unsqueeze(-1)).reshape({Nh * stride_cols, d});
491	        d_k_tok.index_add_(0, g_flat, wk);
492	        d_v_tok.index_add_(0, g_flat, wv);
493	    }
494	
495	    d_q_W.add_(torch::mm(d_q.t(), x));
496	    d_k_W.add_(torch::mm(d_k_tok.t(), x));
497	    d_v_W.add_(torch::mm(d_v_tok.t(), x));
498	    d_x_out.add_(torch::mm(d_q, q_W));
499	    d_x_out.add_(torch::mm(d_k_tok, k_W));
500	    d_x_out.add_(torch::mm(d_v_tok, v_W));
501	}
